import * as Diff from 'diff';

/**
 * Computes an aligned diff between two texts with word-level highlighting
 * @param {string} originalText - The original text
 * @param {string} changedText - The changed text
 * @returns {Array} Array of aligned diff rows
 */
export const computeAlignedDiff = (originalText, changedText) => {
  // Get line-level diff
  const lineDiff = Diff.diffLines(originalText, changedText);

  // Build aligned diff results
  const alignedResults = [];
  let originalLineNum = 0;
  let changedLineNum = 0;

  lineDiff.forEach((part) => {
    const lines = part.value.split('\n');
    // Remove empty last element if exists
    if (lines[lines.length - 1] === '') {
      lines.pop();
    }

    if (!part.added && !part.removed) {
      // Unchanged lines - show on both sides
      lines.forEach((line) => {
        alignedResults.push({
          originalLine: {
            text: line,
            lineNum: ++originalLineNum,
            type: 'unchanged',
            parts: null
          },
          changedLine: {
            text: line,
            lineNum: ++changedLineNum,
            type: 'unchanged',
            parts: null
          }
        });
      });
    } else if (part.removed && !part.added) {
      // Lines only in original (deleted)
      lines.forEach((line) => {
        alignedResults.push({
          originalLine: {
            text: line,
            lineNum: ++originalLineNum,
            type: 'removed',
            parts: [{ value: line, removed: true }]
          },
          changedLine: null
        });
      });
    } else if (part.added && !part.removed) {
      // Lines only in changed (added)
      lines.forEach((line) => {
        alignedResults.push({
          originalLine: null,
          changedLine: {
            text: line,
            lineNum: ++changedLineNum,
            type: 'added',
            parts: [{ value: line, added: true }]
          }
        });
      });
    }
  });

  // Process the aligned results to find modified lines
  // Look for consecutive removed/added pairs and merge them as modifications
  const processedResults = [];
  let i = 0;

  while (i < alignedResults.length) {
    const current = alignedResults[i];
    const next = alignedResults[i + 1];

    // Check if current is removed and next is added (potential modification)
    if (current.originalLine && !current.changedLine && 
        next && !next.originalLine && next.changedLine) {

      // This is a modification - do word-level diff
      const originalText = current.originalLine.text;
      const changedText = next.changedLine.text;

      // Use word-level diff for better readability
      const wordDiff = Diff.diffWords(originalText, changedText);

      // Separate parts for original and changed
      const originalParts = wordDiff.filter(p => !p.added);
      const changedParts = wordDiff.filter(p => !p.removed);

      processedResults.push({
        originalLine: {
          text: originalText,
          lineNum: current.originalLine.lineNum,
          type: 'modified',
          parts: originalParts
        },
        changedLine: {
          text: changedText,
          lineNum: next.changedLine.lineNum,
          type: 'modified',
          parts: changedParts
        }
      });

      i += 2; // Skip both lines
    } else {
      processedResults.push(current);
      i++;
    }
  }

  return processedResults;
};

/**
 * Renders the parts of a diff line with appropriate highlighting
 * @param {Array} parts - Array of diff parts
 * @returns {Array} Array of React elements
 */
export const renderLineParts = (parts) => {
  if (!parts || parts.length === 0) {
    return '\u00A0';
  }

  return parts.map((part, partIndex) => {
    if (part.added) {
      return {
        key: partIndex,
        type: 'added',
        value: part.value
      };
    } else if (part.removed) {
      return {
        key: partIndex,
        type: 'removed',
        value: part.value
      };
    } else {
      return {
        key: partIndex,
        type: 'normal',
        value: part.value
      };
    }
  });
};
